import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/**
 * 非实时交互契约测试：msgid 幂等、异步文件回推、会话+msgid 命名空间隔离。
 *
 * <p>依赖 Redis（与真实部署一致）；不可达则整体跳过，不误报失败。</p>
 *
 * @author IceWright builder
 */
@SpringBootTest
@AutoConfigureMockMvc
class AsyncMessageContractTest {

    @Autowired
    private MockMvc mvc;

    @Autowired
    private SessionService sessionService;

    @Autowired
    private AsyncMessageService asyncMessageService;

    @BeforeEach
    void requireRedis() {
        Assumptions.assumeTrue("ok".equals(sessionService.redisPing()),
            "Redis 不可达，异步契约测试跳过");
    }

    private static String body(String session, String message, String msgid) {
        return "{\"session_id\":\"" + session + "\",\"message\":\"" + message
            + "\",\"msgid\":\"" + msgid + "\"}";
    }

    /** Redis 登记记录跨测试轮次存续，固定 msgid 会命中上轮缓存或上轮失败态——键必须带随机后缀。 */
    private static String uid() {
        return java.util.UUID.randomUUID().toString().substring(0, 8);
    }

    @Test
    void sameMsgidReturnsIdenticalReceipt() throws Exception {
        String payload = body("s-jdup-" + uid(), "理赔需要哪些材料", "m-jdup-" + uid());
        MvcResult r1 = mvc.perform(post("/chat").contentType(MediaType.APPLICATION_JSON).content(payload))
            .andExpect(status().isOk()).andReturn();
        MvcResult r2 = mvc.perform(post("/chat").contentType(MediaType.APPLICATION_JSON).content(payload))
            .andExpect(status().isOk()).andReturn();
        assertEquals(r1.getResponse().getContentAsString(), r2.getResponse().getContentAsString());
    }

    @Test
    void badMsgidCharsetRejected() throws Exception {
        mvc.perform(post("/chat").contentType(MediaType.APPLICATION_JSON)
                .content("{\"session_id\":\"s-jbad\",\"message\":\"x\",\"msgid\":\"bad id/空格\"}"))
            .andExpect(status().isBadRequest());
    }

    @Test
    void asyncRoundtripFilesAndDownload() throws Exception {
        String session = "s-jasync-" + uid();
        String msgid = "m-jasync-" + uid();
        String payload = body(session, "生成理赔材料包", msgid);
        mvc.perform(post("/chat/async").contentType(MediaType.APPLICATION_JSON).content(payload))
            .andExpect(status().isAccepted())
            .andExpect(jsonPath("$.msgid").value(msgid));
        Map<String, Object> view = waitDone(session, msgid);
        assertEquals("ready", view.get("status"));
        @SuppressWarnings("unchecked")
        List<Map<String, Object>> files = (List<Map<String, Object>>) view.get("files");
        assertEquals(1, files.size());
        String downloadUrl = files.get(0).get("download_url").toString();
        assertTrue(downloadUrl.startsWith("/messages/" + msgid + "/files/"));
        mvc.perform(get(downloadUrl))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.msgid").value(msgid))
            .andExpect(jsonPath("$.reply").isString());
    }

    @Test
    void msgidIsolatedBySessionNamespace() throws Exception {
        String session = "s-jiso-a-" + uid();
        String msgid = "m-jiso-" + uid();
        String payload = body(session, "甲会话消息", msgid);
        mvc.perform(post("/chat/async").contentType(MediaType.APPLICATION_JSON).content(payload))
            .andExpect(status().isAccepted());
        assertNull(asyncMessageService.filesView("s-jiso-b-" + uid(), msgid));
        mvc.perform(get("/messages/" + msgid + "/files").param("session_id", "s-jiso-b-" + uid()))
            .andExpect(status().isNotFound());
        assertNotNull(waitDone(session, msgid));
    }

    @Test
    void missingSessionIdRefused() throws Exception {
        mvc.perform(get("/messages/anything/files"))
            .andExpect(status().isBadRequest());
    }

    private Map<String, Object> waitDone(String sessionId, String msgid) throws InterruptedException {
        // 上限须大于模型兜底超时：未配置模型时异步任务在模型超时后仍会落 ready/failed，不该被误判悬挂
        long deadline = System.nanoTime() + java.util.concurrent.TimeUnit.SECONDS.toNanos(40);
        while (System.nanoTime() < deadline) {
            Map<String, Object> view = asyncMessageService.filesView(sessionId, msgid);
            assertNotNull(view, "登记记录不应消失");
            String status = String.valueOf(view.get("status"));
            if ("ready".equals(status) || "failed".equals(status)) {
                return view;
            }
            Thread.sleep(50);
        }
        throw new AssertionError("异步任务未在 40s 内落状态");
    }
}
